import React, { useState, useEffect, useRef } from 'react';
import './index.css';

/* ─── DATA ─── */
const SKILLS = {
  'Programmation': ['Python', 'JavaScript', 'Java', 'PHP', 'HTML', 'CSS'],
  'Frameworks': ['React.js', 'Vue.js', 'Spring Boot', 'Laravel'],
  'Bases de données': ['MySQL', 'PostgreSQL', 'SQLite'],
  'Outils & DevOps': ['Docker', 'Git', 'GitHub', 'Postman', 'VS Code', 'IntelliJ'],
  'IA / Data': ['LangChain', 'FAISS', 'HuggingFace', 'Streamlit'],
};

const PROJECTS = [
  {
    title: 'Chatbot Intelligent RAG',
    tag: 'IA · NLP',
    desc: "Chatbot capable d'interroger des documents PDF et de fournir des réponses précises en langage naturel grâce à l'analyse sémantique du contenu.",
    tech: ['Python', 'Streamlit', 'LangChain', 'FAISS', 'HuggingFace', 'SQLite'],
    accent: '#79A3C3',
  },
  {
    title: 'Plateforme éducative interactive',
    tag: 'Fullstack · IA',
    desc: 'Plateforme interactive pour l\'apprentissage des langages de programmation avec intégration IA.',
    tech: ['React', 'Spring Boot', 'PostgreSQL', 'Git', 'Postman'],
    accent: '#957662',
  },
  {
    title: 'EcoRide – Covoiturage',
    tag: 'Web · Fullstack',
    desc: 'Plateforme de covoiturage éco-responsable avec gestion des trajets, réservations et profils utilisateurs.',
    tech: ['Spring Boot', 'React', 'MySQL', 'Postman', 'Git'],
    accent: '#3A2119',
  },
  {
    title: 'Gestion des Étudiants',
    tag: 'Fullstack · Équipe',
    desc: 'Application web complète de gestion des étudiants, encadrants, propositions de sujets et soutenances.',
    tech: ['Spring Boot', 'Vue.js', 'MySQL', 'Git', 'Postman'],
    accent: '#79A3C3',
  },
  {
    title: 'Gestion de Présence',
    tag: 'Vision · Fullstack',
    desc: 'Système de gestion de présence avec reconnaissance faciale et QR Code pour l\'automatisation.',
    tech: ['Vue.js', 'Laravel', 'MySQL', 'Reconnaissance faciale', 'QR Code'],
    accent: '#EBCDB7',
  },
];

const CERTS = [
  { name: 'Python', issuer: '365 Data Science' },
  { name: 'JavaScript', issuer: 'Cisco' },
  { name: 'Java', issuer: 'DataCamp' },
  { name: 'Git', issuer: 'DataCamp' },
];

/* ─── HOOK: Intersection Observer ─── */
function useVisible(threshold = 0.15) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) setVisible(true); },
      { threshold }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, visible];
}

/* ─── NAV ─── */
function Nav({ active }) {
  const links = ['Accueil', 'Compétences', 'Projets', 'Formation', 'Contact'];
  const ids    = ['home',    'skills',      'projects','formation','contact'];
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 60);
    window.addEventListener('scroll', fn);
    return () => window.removeEventListener('scroll', fn);
  }, []);

  return (
    <nav style={{
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
      background: scrolled ? 'rgba(250,248,245,0.95)' : 'transparent',
      backdropFilter: scrolled ? 'blur(12px)' : 'none',
      borderBottom: scrolled ? '1px solid #D2E2EC' : 'none',
      transition: 'all 0.4s ease',
      padding: '0 5vw',
      height: 64,
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
    }}>
      <span style={{
        fontFamily: 'var(--font-display)',
        fontSize: '1.35rem',
        fontWeight: 600,
        color: 'var(--espresso)',
        letterSpacing: '0.01em',
      }}>
        C<em style={{ color: 'var(--chambray)' }}>.</em>EH
      </span>
      <div style={{ display: 'flex', gap: '2rem' }}>
        {links.map((l, i) => (
          <a key={l} href={`#${ids[i]}`} style={{
            fontFamily: 'var(--font-ui)',
            fontSize: '0.78rem',
            fontWeight: 600,
            letterSpacing: '0.08em',
            textTransform: 'uppercase',
            color: active === ids[i] ? 'var(--chambray)' : 'var(--espresso)',
            textDecoration: 'none',
            opacity: active === ids[i] ? 1 : 0.65,
            transition: 'all 0.2s',
          }}
          onMouseEnter={e => e.target.style.opacity = 1}
          onMouseLeave={e => e.target.style.opacity = active === ids[i] ? 1 : 0.65}
          >{l}</a>
        ))}
      </div>
    </nav>
  );
}

/* ─── HERO ─── */
function Hero() {
  return (
    <section id="home" style={{
      minHeight: '100vh',
      background: `linear-gradient(135deg, var(--espresso) 0%, #5c3527 50%, #3A2119 100%)`,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      position: 'relative', overflow: 'hidden',
      padding: '100px 5vw 60px',
    }}>
      {/* Decorative blobs */}
      <div style={{
        position: 'absolute', top: '-10%', right: '-5%',
        width: 450, height: 450,
        background: 'radial-gradient(circle, rgba(121,163,195,0.18) 0%, transparent 70%)',
        borderRadius: '50%',
        animation: 'float 7s ease-in-out infinite',
      }} />
      <div style={{
        position: 'absolute', bottom: '-5%', left: '-8%',
        width: 350, height: 350,
        background: 'radial-gradient(circle, rgba(235,205,183,0.12) 0%, transparent 70%)',
        borderRadius: '50%',
        animation: 'float 9s ease-in-out infinite reverse',
      }} />
      {/* Grid overlay */}
      <div style={{
        position: 'absolute', inset: 0,
        backgroundImage: `linear-gradient(rgba(210,226,236,0.04) 1px, transparent 1px),
          linear-gradient(90deg, rgba(210,226,236,0.04) 1px, transparent 1px)`,
        backgroundSize: '60px 60px',
      }} />

      <div style={{
        maxWidth: 1100, width: '100%',
        display: 'grid', gridTemplateColumns: '1fr 1fr',
        gap: '4rem', alignItems: 'center',
        position: 'relative', zIndex: 1,
      }}>
        {/* Left */}
        <div>
          <div style={{
            display: 'inline-block',
            fontFamily: 'var(--font-mono)',
            fontSize: '0.72rem',
            letterSpacing: '0.15em',
            textTransform: 'uppercase',
            color: 'var(--chambray)',
            background: 'rgba(121,163,195,0.12)',
            border: '1px solid rgba(121,163,195,0.3)',
            padding: '6px 14px', borderRadius: 4,
            marginBottom: '1.5rem',
            animation: 'fadeUp 0.6s ease both',
          }}>
            Élève ingénieure · ENSA Safi
          </div>

          <h1 style={{
            fontFamily: 'var(--font-display)',
            fontSize: 'clamp(3rem, 6vw, 5.5rem)',
            fontWeight: 300,
            lineHeight: 1.05,
            color: 'var(--bisque)',
            marginBottom: '0.5rem',
            animation: 'fadeUp 0.6s 0.15s ease both',
            opacity: 0,
            animationFillMode: 'forwards',
          }}>
            Chayma
          </h1>
          <h1 style={{
            fontFamily: 'var(--font-display)',
            fontSize: 'clamp(3rem, 6vw, 5.5rem)',
            fontWeight: 600,
            fontStyle: 'italic',
            lineHeight: 1.05,
            color: 'var(--glacier)',
            marginBottom: '1.8rem',
            animation: 'fadeUp 0.6s 0.3s ease both',
            opacity: 0,
            animationFillMode: 'forwards',
          }}>
            EL HOUMA
          </h1>

          <p style={{
            fontFamily: 'var(--font-ui)',
            fontSize: '1rem',
            lineHeight: 1.8,
            color: 'rgba(210,226,236,0.75)',
            maxWidth: 460,
            marginBottom: '2.5rem',
            animation: 'fadeUp 0.6s 0.45s ease both',
            opacity: 0,
            animationFillMode: 'forwards',
          }}>
            Développeuse web full-stack & passionnée d'Intelligence Artificielle. 
            Je construis des applications web intelligentes alliant architecture 
            solide et expériences utilisateur mémorables.
          </p>

          <div style={{
            display: 'flex', gap: '1rem', flexWrap: 'wrap',
            animation: 'fadeUp 0.6s 0.6s ease both',
            opacity: 0,
            animationFillMode: 'forwards',
          }}>
            <a href="#projects" style={{
              background: 'var(--chambray)',
              color: 'var(--white)',
              padding: '12px 28px',
              borderRadius: 6,
              fontFamily: 'var(--font-ui)',
              fontWeight: 700,
              fontSize: '0.82rem',
              letterSpacing: '0.06em',
              textTransform: 'uppercase',
              textDecoration: 'none',
              transition: 'all 0.2s',
            }}
            onMouseEnter={e => { e.target.style.background = '#5d8aad'; e.target.style.transform = 'translateY(-2px)'; }}
            onMouseLeave={e => { e.target.style.background = 'var(--chambray)'; e.target.style.transform = 'translateY(0)'; }}
            >Voir mes projets</a>
            <a href="#contact" style={{
              background: 'transparent',
              color: 'var(--bisque)',
              padding: '12px 28px',
              borderRadius: 6,
              fontFamily: 'var(--font-ui)',
              fontWeight: 700,
              fontSize: '0.82rem',
              letterSpacing: '0.06em',
              textTransform: 'uppercase',
              textDecoration: 'none',
              border: '1.5px solid rgba(235,205,183,0.4)',
              transition: 'all 0.2s',
            }}
            onMouseEnter={e => { e.target.style.borderColor = 'var(--bisque)'; e.target.style.background = 'rgba(235,205,183,0.08)'; }}
            onMouseLeave={e => { e.target.style.borderColor = 'rgba(235,205,183,0.4)'; e.target.style.background = 'transparent'; }}
            >Me contacter</a>
          </div>
        </div>

        {/* Right – avatar card */}
        <div style={{
          display: 'flex', justifyContent: 'center',
          animation: 'fadeIn 1s 0.5s ease both',
          opacity: 0,
          animationFillMode: 'forwards',
        }}>
          <div style={{
            width: 300, height: 380,
            background: 'linear-gradient(145deg, rgba(210,226,236,0.08), rgba(149,118,98,0.08))',
            border: '1px solid rgba(210,226,236,0.2)',
            borderRadius: 16,
            display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            gap: '1rem',
            backdropFilter: 'blur(8px)',
            position: 'relative',
            overflow: 'hidden',
          }}>
            <div style={{
              position: 'absolute', top: 0, left: 0, right: 0, height: 4,
              background: 'linear-gradient(90deg, var(--chambray), var(--bisque), var(--clay))',
            }} />
            {/* Avatar circle */}
            <div style={{
              width: 100, height: 100,
              borderRadius: '50%',
              background: 'linear-gradient(135deg, var(--chambray), var(--clay))',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: '2.5rem',
              fontFamily: 'var(--font-display)',
              color: 'var(--white)',
              fontWeight: 600,
              border: '3px solid rgba(210,226,236,0.3)',
            }}>CE</div>
            <div style={{ textAlign: 'center', padding: '0 1.5rem' }}>
              <p style={{ fontFamily: 'var(--font-ui)', fontWeight: 700, color: 'var(--bisque)', fontSize: '1rem' }}>
                Chayma EL HOUMA
              </p>
              <p style={{ fontFamily: 'var(--font-mono)', fontSize: '0.7rem', color: 'rgba(210,226,236,0.6)', marginTop: 4 }}>
                Génie Informatique & IA
              </p>
            </div>
            {/* Quick stats */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', width: '80%' }}>
              {[['5+', 'Projets'], ['4', 'Certifications'], ['2', 'Clubs Tech'], ['3', 'Langues']].map(([n, l]) => (
                <div key={l} style={{
                  background: 'rgba(255,255,255,0.04)',
                  border: '1px solid rgba(210,226,236,0.15)',
                  borderRadius: 8, padding: '10px 8px',
                  textAlign: 'center',
                }}>
                  <div style={{ fontFamily: 'var(--font-display)', fontSize: '1.6rem', fontWeight: 600, color: 'var(--chambray)' }}>{n}</div>
                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.62rem', color: 'rgba(210,226,236,0.5)', letterSpacing: '0.05em' }}>{l}</div>
                </div>
              ))}
            </div>
            {/* Status badge */}
            <div style={{
              display: 'flex', alignItems: 'center', gap: 6,
              background: 'rgba(121,163,195,0.12)',
              border: '1px solid rgba(121,163,195,0.3)',
              borderRadius: 20, padding: '5px 12px',
              fontFamily: 'var(--font-mono)', fontSize: '0.65rem',
              color: 'var(--chambray)',
            }}>
              <div style={{ width: 6, height: 6, borderRadius: '50%', background: '#79A3C3', animation: 'spin 2s linear infinite' }} />
              Disponible · Juil–Août 2026
            </div>
          </div>
        </div>
      </div>

      {/* Scroll indicator */}
      <div style={{
        position: 'absolute', bottom: 30, left: '50%', transform: 'translateX(-50%)',
        display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6,
        animation: 'float 2s ease-in-out infinite',
      }}>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.12em', color: 'rgba(210,226,236,0.4)', textTransform: 'uppercase' }}>Scroll</span>
        <div style={{ width: 1, height: 40, background: 'linear-gradient(to bottom, rgba(210,226,236,0.4), transparent)' }} />
      </div>
    </section>
  );
}

/* ─── SKILLS ─── */
function Skills() {
  const [ref, visible] = useVisible();
  return (
    <section id="skills" ref={ref} style={{
      padding: '120px 5vw',
      background: 'var(--white)',
    }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <SectionHeader label="Compétences" title="Ce que je maîtrise" dark={false} visible={visible} />
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))',
          gap: '1.5rem',
          marginTop: '3.5rem',
          opacity: visible ? 1 : 0,
          transform: visible ? 'none' : 'translateY(20px)',
          transition: 'all 0.8s 0.3s ease',
        }}>
